# English lecture content. Each section becomes one horizontal Reveal.js stack.
A='Access'; F='Files in VS Code'; C='Shell essentials'; J='Slurm jobs'; P='Software and packages'; R='Run and check'

BATCH=[
('#!/bin/bash','Use Bash to read the commands.'),
('#SBATCH --job-name=hello','Give the job a recognizable name.'),
('#SBATCH --account=YOUR_ACCOUNT','Use the Slurm account assigned to your group.'),
('#SBATCH --partition=YOUR_PARTITION','Use a partition that this account can access.'),
('#SBATCH --nodes=1','Request one compute node.'),
('#SBATCH --ntasks=1','Request one task for this program.'),
('#SBATCH --cpus-per-task=1','Reserve one CPU for that task.'),
('#SBATCH --mem=1G','Request 1 GiB of RAM per node.'),
('#SBATCH --time=00:05:00','Set a five-minute running-time limit.'),
('echo "My first HPC job"','Print a message into the job output.')]


S('Getting started on the<br>Illinois Campus Cluster',
  '<div class="cover-copy"><p class="cover-sub">A practical workflow for data analysis</p></div>'+img('cluster-photo.png','University of Illinois computing hardware','','cover-photo'),
  'Hi everyone, I’m from Kun Wang’s lab. We mainly do computational work, so for us, HPC is a bit like the lab bench in a wet lab—it’s where we run our analyses. Today, I’ll give you a brief introduction to the Illinois Campus Cluster and walk through the basic skills you need to run computationally intensive analyses on it.',['computes'],A,'cover')

S('Prepare files on login nodes; run jobs on compute nodes',
  img('icc-overview.png','Official NCSA Campus Cluster usage overview','HPC = high-performance computing. A node is one computer. Login: prepare files. Compute: run scheduled analysis.','overview-image'),
  'Before we connect, it helps to know what we’re connecting to. HPC means high-performance computing. A cluster is a group of connected computers, and each computer is called a node. In this diagram, our laptop connects to the head node, which we’ll call the login node.\n\nThat’s where we organize files, edit scripts, and submit work. Other people share this node, so we use compute nodes for the heavier analysis. To do that, we submit a job: we tell the scheduler what program we want to run and what resources it needs. The scheduler starts it when those resources are available.\n\nBoth kinds of node can access the project files through shared storage. Connecting with VS Code gives us access to those files, but it doesn’t reserve a compute node. Before any of this works, we need an approved account and permission to use the group’s resources.',
  ['start','jobs'],
  A,
  'image-slide')

S('Request access and confirm your allocation details',
  cols(rows([('Existing lab access','Ask your PI or technical contact which cluster group to join.'),('A new computing need','Start an Illinois Computes request.')]),table(['Detail to confirm','Used for'],[['NetID','Your login identity'],['Slurm account','The group’s assigned computing resources'],['Partition','A queue you may submit to'],['Project path','A folder where you have permission to save files']]))+'<div class="link-row"><a href="https://campuscluster.illinois.edu/new_forms/user_form.php" target="_blank">Research access request ↗</a><a href="https://computes.illinois.edu/submitrequest/" target="_blank">Illinois Computes request ↗</a></div>'+p('Before connecting: get account approval, confirm these four details, and set up Duo.','small'),
  'For access, I’d start with your PI or the person who manages computing for your group. If the group already uses the cluster, they can tell you which group to join. You may see the term investor group—that means a lab or organization that has arranged cluster resources. For a new computing need, Illinois Computes is another starting point. The form starts the request; we still need approval and account setup before we can log in.\n\nThere are four details we’ll use throughout the talk. Your NetID identifies you. Your Slurm account identifies the group resources your job can use, so it isn’t the same as your NetID. Slurm is the software that schedules jobs. The partition is a queue of eligible resources, and the project path tells us where we can save files.\n\nAsk for an account and partition that work together, a folder you can write to, and help setting up Duo if needed. Anywhere you see something like YOUR_NETID, replace it with your own value. With those details ready, we can try the first connection.',['access','routes','request','jobs'],A)

S('The first SSH login',
  code('ssh YOUR_NETID@cc-login.campuscluster.illinois.edu','On your laptop: open Terminal (macOS) or PowerShell (Windows)')+p('<code>ssh</code> starts the connection · before <code>@</code>: your user name · after <code>@</code>: the cluster address','small')+cols(rows([('1 · Run the command','Replace YOUR_NETID, then press Enter.'),('2 · Password','Type your NetID password and press Enter; typing stays hidden.'),('3 · Duo','Follow the prompt and approve the authentication request.')]),img('icc-login.png','Official example of a successful ICC login','A welcome message and cluster command prompt confirm login. Screenshot dates and quotas are historical.','login-image')),
  'We’ll start with a quick connection from the laptop. On a Mac, open Terminal; on Windows, open PowerShell. If Windows doesn’t recognize ssh, you’ll need to enable the OpenSSH Client first.\n\nIn this line, ssh starts the connection. Your NetID goes before the at sign, and the cluster address goes after it. Replace YOUR_NETID, leave the hostname as shown, and press Enter.\n\nThe first time, SSH may ask you to confirm the server’s identity. Check that fingerprint against institutional guidance or with support before accepting it. If you get an unexpected warning that the host has changed, check that too. Then enter your NetID password. You won’t see anything appear as you type—that’s normal. Complete the Duo prompt on your registered device. ICC uses your password and Duo here, rather than user-created SSH keys.\n\nOnce we see the welcome message and a command prompt, we’re connected. The prompt tells us the shell is ready, and commands typed here run on the cluster. The screenshot is an older example, so its dates and quota numbers aren’t current guidance. We can type exit to close this test connection without deleting anything. VS Code will make its own connection, so let’s look at that tool next.',['access'],A,'compact')

S('VS Code is an editor for code and project files',
  '<div class="vscode-intro-grid">'+img('vscode-interface.png','Official Microsoft VS Code screenshot showing the Explorer, code editors, and terminal','Microsoft example: B = files, C = editor, D = terminal panel.','vscode-interface-image')+'<div class="vscode-intro-copy">'+p('Visual Studio Code (VS Code) is Microsoft’s code editor for working with scripts and project files.')+rows([('B · Explorer','Browse files and folders in the left sidebar.'),('C · Editor','Read and edit scripts in the main area.'),('D · Terminal','Enter commands in the bottom panel.')])+'</div></div>',
  'This is Visual Studio Code, or just VS Code. It’s Microsoft’s editor for code and project files. The useful thing is that we can browse files, edit them, and use a terminal in one window. When I say script, I mean a text file containing instructions for a program to run.\n\nThis screenshot is Microsoft’s example, so we won’t be using these particular files or this code. The area marked B is Explorer, where we browse folders and files. The areas marked C show the files we’ve opened in the editor. Down at D is the terminal, where we enter commands. That bottom panel can show other things too, but here it’s showing a terminal.\n\nThose are the three areas we’ll keep coming back to: files on the left, editing in the main area, and commands in the terminal. We can also use this same window to work with files on the cluster.',['vscode_ui'],F,'vscode-intro')

S('Use local VS Code to edit files on the cluster',
  img('vscode-architecture.png','Microsoft Remote - SSH architecture showing the local editor and remote files','Microsoft diagram: the laptop editor connects over SSH to remote project files.','wide-image')+rows([('On your laptop','The VS Code window and its controls'),('On the cluster','The project files and commands from the remote terminal')])+note('Open, edit, and save cluster files directly in the VS Code window.'),
  'Here’s why I recommend VS Code for this workflow. The window stays on your laptop, but it can open files stored on the cluster. Microsoft’s Remote - SSH extension makes that connection using SSH.\n\nOn the left of the diagram is the editor we’re looking at. On the right is the remote computer, where the project files and the processes behind the remote terminal live. Once they’re connected, we can open a remote file, make a change, and save it straight back to the cluster. We don’t have to download it, edit a local copy, and upload it again every time.\n\nWe’ll still use Slurm to get resources for an analysis. This connection is how we reach the files. The part that can feel confusing at first is that the window is on one computer while the files and commands are on another. Let’s make that a little more concrete.',['vscode'],F)

S('Files stay on the cluster; terminal commands run there',
  concept_diagram('local-remote')+note('In the SSH window, saves update cluster files and terminal commands run on the connected host.'),
  'Suppose we’ve opened analysis.py in this connected VS Code window. We’re looking at it on the laptop, but the file itself is demo/analysis.py on the cluster. When we press Save, that remote file is the one that changes. This picture shows where we’ll end up after uploading the project; we’ll walk through those steps in a moment.\n\nThe terminal works in a similar way. We see it on the laptop screen, but its commands run on the connected cluster host. Our first connection goes to a login node. If we opened a separate local terminal, its commands would run on the laptop instead. Later, an interactive job will let us open a shell on a compute node, so we’ll check which host we’re using.\n\nFor everyday file work, we can open, edit, and save directly in this window. To get that working, we need VS Code and the Remote - SSH extension on the laptop.',['vscode','prog'],F,'concept-slide'),

S('Install VS Code and the Remote - SSH extension',
  rows([('Install VS Code','Download, install, and open the desktop application.'),('Open Extensions','Click the Extensions icon in VS Code’s left sidebar.'),('Search','Enter Remote - SSH; choose the extension published by Microsoft.'),('Install','Click Install for Remote - SSH and wait until installation finishes.')])+'<div class="link-row"><a href="https://code.visualstudio.com/docs/setup/setup-overview" target="_blank">Official VS Code setup ↗</a></div>'+note('This installs the editor and connection tool on your laptop.'),
  'There are two things to install on the laptop. First, download VS Code for your operating system, install it, and open it. Then click the Extensions icon in the sidebar. Extensions are add-ons that give the editor extra features.\n\nSearch for Remote - SSH and look for Microsoft as the publisher. Click Install and wait for it to finish. That adds the commands we need to connect to the cluster.\n\nAt this point, we’ve prepared the editor on the laptop. We’ll set up Python and the analysis packages on the cluster separately, when we get to software setup.\n\nTo start the connection, we’ll use something called the Command Palette. It’s a searchable menu of VS Code actions, so we can type the name of the action we want. We’ll use it with the same NetID and cluster hostname that worked in our SSH test.',['vscode_setup','vscode'],F)

S('Connecting VS Code with Remote - SSH',
  rows([('Command Palette','Cmd+Shift+P on macOS; Ctrl+Shift+P on Windows/Linux'),('Choose','Remote-SSH: Connect to Host…'),('Enter and sign in','YOUR_NETID@cc-login.campuscluster.illinois.edu')])+img('vscode-host.png','Microsoft example of the Connect to Host selector','Microsoft example UI. Enter your NetID and the ICC hostname in this field.','host-image')+p('Sign in with password + Duo. Choose Linux if asked. Confirm the lower-left SSH indicator names the cluster.','small'),
  'To open the Command Palette, press Command-Shift-P on a Mac, or Control-Shift-P on Windows or Linux. Search for Remote-SSH: Connect to Host. Then enter your NetID and the cluster hostname, just as we did in the terminal connection.\n\nYou’ll go through the password and Duo prompts again. If VS Code asks which operating system the remote computer uses, choose Linux—that’s what the cluster runs. It may open a separate connected window.\n\nTo check that it worked, look at the SSH indicator in the lower-left corner. It should name the cluster host. That tells us this window is connected to the remote computer. If it seems stuck waiting, check the Remote - SSH output or login terminal; there may be an authentication prompt waiting for a response.\n\nOnce we’re connected, we need somewhere to put our project. We’ll choose that location before uploading the files.',
  ['prog','vscode'],
  F,
  'compact')

S('Choose home, project, or scratch storage',
  table(['Location','Use it for','Limits and actions'],[['/u/YOUR_NETID','Settings and small personal files','Very limited quota: 100 GiB (soft limit). Keep large datasets elsewhere.'],['/projects/YOUR_GROUP','Group data, software, and retained outputs','Shared group quota. Keep backups: no snapshots are kept for file recovery.'],['/scratch/YOUR_NETID','Temporary working data','Temporary only: files typically deleted after 30 days without access, sometimes sooner.']])+note('Use your group’s full project path; <code>/projects/YOUR_GROUP</code> is a placeholder.'),
  'Before we upload anything, we need to choose where it will live. Home, project, and scratch storage have different jobs.\n\nHome, under /u, is for settings and small personal files. It has a very limited quota, which means a limit on how much space you can use: 100 GiB as the documented soft limit and 103 GiB as the hard limit. If you stay above the soft limit for seven days, new writes stop until you reduce your usage. You can’t expand the home quota, so it’s a poor place to collect large datasets.\n\nProject storage is shared by the group, and the available space depends on its allocation. It has no snapshots—saved filesystem states that let you recover earlier files—so important data need a separate backup plan.\n\nScratch is temporary workspace. Files are typically deleted after 30 days without access, sometimes sooner if space is tight. Once purged, they can’t be recovered, so move valuable outputs elsewhere.\n\nFor our project, we’ll use the full path supplied by the group, where we have permission to save files. The path on the slide is a placeholder. We’ll open that parent folder first, then upload demo into it.',['storage'],F,'storage-slide')

S('Open the remote project location',
  img('vscode-folder.png','Microsoft example of opening a folder over SSH','Microsoft example UI. Replace its sample path with your assigned project location.','folder-image')+rows([('File → Open Folder','Open /projects/YOUR_GROUP or your assigned path.'),('Check the connection','Confirm the lower-left SSH indicator names the cluster.'),('Check Explorer','It should show the group folder that will receive demo.')])+note('The Explorer now shows the remote location, before the upload.'),
  'We’ve chosen a storage location, so we can open it in VS Code. In the connected window, go to File, then Open Folder, and enter your approved group path. Here, /projects/YOUR_GROUP stands for the parent folder where we’ll put demo.\n\nMicrosoft’s screenshot uses a path from its own example system. Yours should be the full path your group gave you. Also check that the SSH indicator still names the cluster. With that connection active, the folders in Explorer are on the remote computer.\n\nAt this point, we’ve opened the destination, but we haven’t uploaded anything yet. The demo folder is still on the laptop. It helps to keep those two locations clear: the folder we’re taking from the laptop, and the folder we’re putting it into on the cluster. Next, we’ll make that transfer.',['vscode'],F,'compact')

S('Upload the demo folder with VS Code',
  rows([('On the laptop','Unzip the offline package; find HPC_Introduction/demo.'),('Upload','Drag demo into the remote Explorer destination.'),('Open the project','File → Open Folder → /projects/YOUR_GROUP/demo'),('Check a file','Open data/samples.csv and look for the three sample rows.')])+note('After upload finishes, open data/samples.csv from the remote Explorer to check it arrived.'),
  'The offline package includes a small demo folder with the input file and scripts we’ll use. After unzipping it on the laptop, look inside HPC_Introduction. Drag the whole demo folder into the remote Explorer destination. Aim for the file list in Explorer, rather than an open editor tab.\n\nOnce the transfer finishes, use File, Open Folder again and open the uploaded demo folder. The example path is /projects/YOUR_GROUP/demo; yours will use the group’s actual location. Expand data and open samples.csv. We should see a header and three sample rows. That checks that the file arrived and we can read it on the cluster.\n\nFrom here, Command-S or Control-S saves our edits directly to the remote file. Dragging files is convenient for this small example. For a large dataset, use the transfer service your group recommends, such as Globus, and check that the transfer finishes before starting the analysis.\n\nOur files are in place. We can open a terminal in this same project folder next.',['vscode','transfer','storage'],F,'compact')

S('Open a terminal in the same project',
  code('hostname\ncd /projects/YOUR_GROUP/demo\npwd','VS Code → Terminal → New Terminal')+rows([('hostname','Print the host name; expect a login node here.'),('cd','Change to the remote project folder shown in Explorer.'),('pwd','Print the full current folder path.')])+note('Run one line, press Enter, wait for the prompt, then continue.'),
  'We’ve been working with files through the interface. For the next steps, we’ll also use a few commands. In the remote VS Code window, choose Terminal, then New Terminal. The terminal is the text window; the shell is the program that reads what we type. Here, that shell runs on the connected cluster host.\n\nWe’ll use these three lines one at a time. hostname tells us which computer we’re on. At this stage, we expect a login host, such as cc-login1. Then cd changes the current folder to our uploaded project. Use your group’s full path in place of the example. Finally, pwd prints the full path, so we can check that the terminal is working in the same folder we opened in Explorer. If cd works, it usually doesn’t print anything.\n\nWhen the prompt comes back, the shell is ready for another command. In our examples, the dollar sign marks that prompt; we don’t type it ourselves. These short file checks are fine on the login node. We’ll send the actual analysis to compute resources later. First, we’ll break down how a command is written.',['shell'],C)

S('Read the program, options, and path in a command',
  '<div class="hero-code"><span class="accent">head</span> <span class="teal">-n 5</span> <span class="gold">data/samples.csv</span></div>'+rows([('Program','head displays the beginning of a text file.'),('Option + value','-n 5 asks for the first five lines.'),('File path','data/samples.csv is the path to the file to read.')])+note('Quotes keep a path together: <code>head -n 5 "data/samples.csv"</code>. They are required for paths containing spaces.'),
  'A command can look like a long string at first, but we can read this one in three parts. head is the program we’re asking to run. The option -n, followed by 5, says we want the first five lines. Then data/samples.csv tells it which file to read. If the file has fewer than five lines, it just shows the lines that are there.\n\nEverything after head is an argument. Some arguments change what the program does; others give it a value or a filename. An option letter belongs to that particular command, so the same letter can mean something else in a different program.\n\nSpaces usually separate the arguments. If a path contains spaces, quotes keep the whole path together. The quoted example on this slide works too, but this particular path doesn’t need quotes because it has no spaces.\n\nWe’ll use this way of reading commands throughout the talk. Before trying more file commands, we need to know how the folder we’re currently in affects the path we type.',['shell','cli'],C)

S('Navigate the uploaded project',
  cols(transcript('$ pwd\n/projects/YOUR_GROUP/demo\n$ cd data\n$ pwd\n/projects/YOUR_GROUP/demo/data\n$ cd ..\n$ pwd\n/projects/YOUR_GROUP/demo\n$ cd ~\n$ pwd\n/u/YOUR_NETID\n$ cd -\n/projects/YOUR_GROUP/demo\n$ pwd\n/projects/YOUR_GROUP/demo','Transcript: type commands after $; other lines are output'),table(['Command','Meaning'],[['pwd','Print the current folder'],['cd data','Enter the data subfolder'],['cd ..','Go up one folder'],['cd ~','Go to your home folder'],['cd -','Return to the previous folder']])+p('<code>cd -</code> also prints its destination. The next <code>pwd</code> confirms it.','small'))+p('<code>.</code> current folder · <code>..</code> parent · <code>/projects/…</code> absolute path · <code>data/…</code> relative path','small'),
  'Once we’re in the terminal, the first thing I want to know is where we are. That’s what pwd tells us. Here, we’re starting in demo. cd data takes us into the data folder, and the next pwd shows the new path. cd .. takes us one level up, back to demo. Those two dots mean the parent folder.\n\ncd ~ takes us home, which is shown here as /u/YOUR_NETID. Then cd - takes us back to the folder we were in before, so here we return to demo. That’s different from going up one level. cd - also prints the destination itself, which is why we see the path again when we run pwd.\n\nA path beginning with a slash is an absolute path: it gives the location from the filesystem root. A relative path, like data, starts wherever we are now. One dot means this folder, two dots mean its parent, and the tilde means home. Capitalization matters in file and folder names.\n\nIn this transcript, we type what comes after the dollar sign. The other lines are the computer’s response. We’re back in demo now, so we can list what’s in data without moving into it.',['shell'],C,'compact navigation-examples')

S('List files and inspect their details',
  cols(table(['Command','What changes'],[['ls','List visible file and folder names'],['ls -a','Include hidden names beginning with a dot'],['ls -l','Show details such as size and date'],['ls -lh','Use readable sizes, such as K or M'],['ls -lah','Show hidden names, details, and readable sizes']]),transcript('$ ls data\nsamples.csv\n$ ls -a data\n.  ..  samples.csv\n$ ls -l data\n-rw-r--r-- 1 user group 58 Oct 27 10:00 samples.csv\n$ ls -lh data\n-rw-r--r-- 1 user group 58 Oct 27 10:00 samples.csv\n$ ls -lah data\ndrwxr-xr-x 2 user group 4.0K Oct 27 10:00 .\ndrwxr-xr-x 3 user group 4.0K Oct 27 10:00 ..\n-rw-r--r-- 1 user group   58 Oct 27 10:00 samples.csv','Illustrative listing lines; total lines omitted'))+p('The CSV is only <strong>58 bytes</strong>, so <code>-h</code> still shows 58. Later, <code>ls -a</code> will reveal the <code>.venv</code> folder we create.','small'),
  'We’ve found the folder. To see what’s inside, we use ls. Each example here lists data, and our terminal stays in demo throughout.\n\nPlain ls shows the visible names. With -a, we also see names that begin with a dot. That includes the single dot for the current folder and the two dots for its parent. Later, we’ll use -a in our project folder to see .venv, the hidden folder that holds our Python environment.\n\nThe -l option gives us a longer listing. Reading across, we get permissions, a link count, the owner and group, the size, the modification time, and the name. For our purposes, the filename and size are usually the first things to check. The users and dates here are just examples.\n\nAdding -h makes larger sizes easier to read, with units like K and M. Our little CSV is only 58 bytes, so it still says 58. We can combine the options as -lah to get hidden entries, details, and readable sizes together. A folder’s size on this line isn’t the total of everything inside it; we’ll use du for that.\n\nWe can see our input file. Next, we’ll look at the commands for organizing files and making an output folder.',['shell','cli'],C,'compact listing-examples')

S('Creating, copying, moving, and deleting',
  table(['Command','Result'],[['<code>mkdir results</code>','Create one new folder'],['<code>mkdir -p results/qc</code>','Create missing folders along the path; accept existing folders'],['<code>cp -i notes.txt notes_backup.txt</code>','Copy a file; ask before overwriting'],['<code>cp -r data data_backup</code>','Copy the folder and all its subfolders to a new location'],['<code>mv -i notes_backup.txt notes_old.txt</code>','Rename or move; ask before overwriting'],['<code>rm -i notes_old.txt</code>','Ask before deleting this file']])+p('<code>cp</code> and <code>mv</code>: source first, destination second. Shell deletion normally has no Trash recovery.','small'),
  'These are the basic file operations you’ll use in a project. You can also do most of them through VS Code’s Explorer, but it’s useful to recognize the commands when you see them in instructions.\n\nmkdir results makes a new folder called results. If it’s already there, plain mkdir reports an error. With mkdir -p results/qc, the -p creates any missing folders along the path and accepts ones that already exist.\n\nFor both cp and mv, read the source first and the destination second. cp makes a copy. mv moves the original, or renames it when the destination is a new name in the same folder. The -i asks before replacing a file that’s already at the destination. With cp -r, we copy a folder and its subfolders. Here, data_backup is a new destination. For a large dataset, that extra copy also takes extra storage.\n\nrm -i asks before deleting notes_old.txt. Check the name before confirming, because shell deletion normally has no Trash recovery. These commands often finish without printing anything. We can use ls to check what changed, then open a file to see what’s inside.',['shell','script'],C,'compact')

S('Inspecting a small text file',
  cols(table(['Command','Use'],[['<code>cat notes.txt</code>','Print the entire small file'],['<code>head -n 5 data/samples.csv</code>','Print up to 5 lines from the start'],['<code>less notes.txt</code>','Browse text; press q to leave']]),code('sample_id,reads\nsample_A,1000\nsample_B,1500\nsample_C,1200','Output of head for the included sample table'))+note('Preview a few rows before running the analysis. Avoid printing a huge file with <code>cat</code>.'),
  'Sometimes we just need a quick look at a file. cat prints the whole text file in the terminal, which works well for a short note or a small configuration file. For something large, I’d start with head so the terminal doesn’t fill up with thousands of lines.\n\nHere, head -n 5 asks for up to five lines from the beginning of samples.csv. This file only has four lines, so we get all four. The first gives us the column names, and the other three contain our sample names and example values. The commas separate the fields.\n\nFor a longer text file, less gives us a viewer we can scroll through. Press q when we’re done, and we’re back at the shell prompt. These tools read ordinary text. Images, saved R objects, and other binary files need a suitable viewer. We can also open small text files directly in VS Code.\n\nOnce we can read a file, the next useful step is finding a particular file or a line inside it.',['shell','cli'],C,'compact')

S('Find a file, then find text inside it',
  code('find data -type f -name "*.csv"','Search filenames within data and its subfolders')+rows([('-type f / -name','Keep files only / match their names against the pattern.'),('"*.csv"','The * matches any text before .csv.')])+code('grep -n "sample_B" data/samples.csv','Search inside this file; -n includes line numbers')+code('3:sample_B,1500','Expected grep output: line 3 contains the match'),
  'There are two kinds of searching here. We might know the kind of file we want, or we might know some text that should be inside it.\n\nfind handles the first case. Here, data tells it where to start searching, and -type f keeps regular files in the results. Then -name checks their names against the pattern. In "*.csv", the star can stand for any text before .csv. The quotes let find receive that pattern directly, without the shell expanding it first. In our small project, it should return data/samples.csv.\n\ngrep searches the text inside a file. Here, we’re looking for sample_B in samples.csv. The -n adds a line number, so 3:sample_B,1500 tells us the match is on line three.\n\nBoth commands leave the file unchanged. Starting in the relevant project folder helps keep the results manageable. We’ve found our file and a specific row; next, we can check how many lines it contains and how much storage it uses.',['script','cli'],C,'compact')

S('Count lines and check disk usage',
  cols(code('wc -l data/samples.csv','Run this command')+code('4 data/samples.csv','Expected output; do not type this line'),rows([('wc -l','Count lines in this text file.'),('4 lines','One header plus three sample rows.')]))+code('du -sh data','Check space used by the input folder')+p('<code>-s</code> gives one summary total · <code>-h</code> uses readable units such as K or M','small')+note('<code>wc -l</code> includes header lines. <code>du</code> shows space used; <code>quota</code> shows usage and limits.'),
  'A quick line count can help us check an input file before we run anything. Here, wc -l returns four, followed by the filename. That’s one header line and three sample rows. Strictly speaking, it counts newline characters; all four lines in this example end with one.\n\nWe do need to know the file format before treating that number as a sample count. A different file might have comments, several header lines, or one record spread over multiple lines.\n\nFor storage, du -sh data tells us how much disk space the data folder uses. The -s asks for one summary total, and -h gives us readable units like K or M. The exact value can vary with the filesystem.\n\nThat tells us what the folder is using. To see how much storage we’re allowed to use as well, we run quota, which reports usage and limits for the filesystem areas we can access. We don’t have to memorize all these options; the next slide shows where to look them up.',['cli','storage'],C,'compact')

S('Help and everyday terminal shortcuts',
  table(['Command / key','What it does'],[['<code>man ls</code>','Open the manual; press q to leave'],['<code>head --help</code>','Show the Linux command’s built-in help'],['Tab','Complete a file or folder name'],['↑ / <code>history</code>','Recall previous commands / list shell history'],['Ctrl+C','Interrupt the command currently running in this terminal'],['<code>clear</code> / <code>exit</code>','Clear the display / leave the current shell']])+p('Keep this login shell open for job submission; exit closes it.','small'),
  'You don’t need to learn every command option by heart. I’d much rather know how to look one up. man ls opens the manual for ls, and q gets us out of that viewer. Many programs also have --help, like head does here. These examples are for the cluster’s Linux shell; the tools on a laptop can have slightly different options.\n\nA few keyboard shortcuts make everyday work easier. Tab completes file and folder names. The up arrow brings back a previous command, so we can check it or edit it before pressing Enter. history shows a list of earlier commands.\n\nCtrl+C interrupts the command currently using this terminal. A batch job submitted separately through Slurm keeps running. clear just clears the display. exit leaves the current shell, so what it closes depends on where we are: it could leave a compute allocation or end the SSH connection.\n\nFor now, we’ll keep this login shell open. We have the file commands we need, so we can move on to submitting a job.',['shell','cli'],C,'compact')

S('Slurm runs work on allocated resources',
  concept_diagram('login-compute')+p('<strong>Batch:</strong> submit a script. <strong>Interactive:</strong> request a compute shell with <code>srun</code>.','small')+note('Submit on the login node; the job runs on an allocated compute node.'),
  'This is where Slurm comes in. We prepare the script on the login node, then use sbatch to send it to the scheduler. Slurm checks the resources we’ve requested and may put the job in a queue until they’re available. Once it allocates those resources, meaning reserves them for our job, the program runs on a compute node.\n\nThe shared folder underneath the diagram connects the two sides. Both nodes can access our approved project folder, so the job can read the inputs and write its outputs there. We don’t have to copy the whole project to another computer each time. Slurm is the scheduling software in the middle; the files stay in that shared storage.\n\nOur terminal stays on the login node after submission. The batch job can keep running even if we disconnect the laptop. Later, we’ll also use an interactive job, which gives us a shell on allocated compute resources for software setup.\n\nFirst, though, we’ll look inside hello.sbatch and see what we’re actually asking Slurm to do.',['jobs','sbatch','srun'],J,'concept-slide'),

S('Read a Slurm batch script line by line',
  annotated(BATCH)+p('Edit these lines inside hello.sbatch in VS Code, then save. Submit it from the terminal after reviewing the resource settings.','small'),
  'This little file is the complete request for our first job. hello.sbatch is just plain text: it tells Slurm what resources we need, then tells the computer what to run.\n\nThe first line selects Bash to read the commands. The lines starting with #SBATCH are the settings for Slurm, and they go before the commands that run the program. The job name helps us recognize this submission. The account identifies our group’s compute allocation, and the partition selects a queue we can use. We need a valid account and partition pair from our group.\n\nThe next lines ask for nodes, tasks, CPUs per task, memory, and a running-time limit. At the bottom, echo prints the message. The five-minute limit starts when the job runs; time spent waiting in the queue doesn’t count.\n\nWe’ll edit and save this file in VS Code, then submit it with sbatch. If we ran bash hello.sbatch directly, Bash would treat the #SBATCH lines as comments and run the command on the current machine, without requesting resources.\n\nBefore submitting, I want to slow down on nodes, tasks, and CPUs, because those names are easy to mix up.',['sbatch'],J,'beginner-script')

S('Set nodes, tasks, CPUs, memory, and time for a job',
  p('Example resource request: count the node, the tasks, then the CPUs.','small')+concept_diagram('resource-hierarchy')+p('Reserving resources does not launch the tasks or make the program parallel.','small')+'<div class="resource-demo"><strong>Keep hello.sbatch at: 1 node · 1 task · 1 CPU/task</strong><div><code>--mem=1G</code><span>1 GiB of RAM per node</span><code>--time=00:05:00</code><span>Runtime limit: hours:minutes:seconds</span></div></div>',
  'I find this easier to understand by counting the boxes. The big box is one node, so one computer. Inside it are two tasks, which represent two program processes across the whole job. Each task has two CPUs reserved. Two tasks times two CPUs per task gives us four CPUs in total. ntasks already counts tasks across all the nodes, so we don’t multiply by the node count again.\n\nA task here isn’t a sample or a file. These boxes show what we’re requesting, rather than every CPU the computer physically has. Depending on the system, a Slurm CPU can mean a core or a hardware thread.\n\nThere’s another step between requesting resources and using them. Plain python analysis.py starts one process. Running multiple processes needs a suitable program and launcher, and a multithreaded program needs its own worker or thread setting.\n\nFor our actual hello job, we’ll keep it small: one node, one task, and one CPU. --mem=1G requests one GiB of RAM per node. That’s working memory, not disk storage. --time=00:05:00 allows five minutes of running time, with queue waiting excluded. For a real analysis, we’d choose these values based on the software and data.\n\nWith those settings clear, we’re ready to submit hello.sbatch.',['sbatch'],J,'concept-slide resource-slide')

S('Submit the first job: hello.sbatch',
  code('pwd\nls hello.sbatch\nsbatch hello.sbatch','In the remote demo folder, after saving the file')+code('Submitted batch job 123456','Example response; record the ID returned by your submission')+note('This first job prints a message. It does not run analysis.py yet.'),
  'Before submitting, we need the approved account and partition in the file, and we need to save that file on the cluster. In the terminal, pwd confirms that we’re in our project folder. Then ls hello.sbatch checks that the file is there.\n\nThe submission itself is sbatch hello.sbatch. That sends the saved file to Slurm. If the submission is accepted, we get a job ID back. Here it’s 123456, but yours will be the number in your actual response. Keep that number: we’ll use it to check status, find the output, or cancel the job if needed.\n\nAccepted doesn’t mean started, and it doesn’t mean finished. The job may still be waiting for resources. Saving the file or pressing Run in the editor also doesn’t do this submission step.\n\nOur first job only prints a message. That lets us check the submission process before adding analysis software. We can now look at the queue to see where the job is.',['sbatch'],J)

S('Checking the queue and stopping a job',
  code('squeue -u YOUR_NETID','-u selects your user; run squeue again to refresh the snapshot')+table(['State','Meaning'],[['PD','Pending: queued; check the listing for the reason'],['R','Running: the job is using its assigned resources']])+code('scancel 123456','Only for an unwanted job; let hello finish in this example')+p('After hello leaves the queue: <code>cat slurm-123456.out</code> → <strong>My first HPC job</strong>. Use your job ID.','small'),
  'Once we have a job ID, squeue is how we check whether the job is waiting or running. The -u limits the list to the NetID we give it. Each time we run it, we get a snapshot, so we can run it again for an update.\n\nPD means pending. The job is in the queue, and the listing gives a reason for the wait. R means running. This hello job is so small that it might finish before we even check.\n\nIf we submitted the wrong job, scancel followed by its ID would stop it. Here, we’d let hello finish so we can read its message. Ctrl+C in a log viewer won’t cancel that batch job.\n\nAfter it leaves the queue, we use cat to read slurm-123456.out in the submission folder, replacing the number with our actual job ID. We’re looking for My first HPC job. Disappearing from the queue alone doesn’t tell us it succeeded; we still check the output and investigate anything missing or unexpected.\n\nFor a larger analysis, clearer log names and email notifications can make this easier to follow.',['jobs','states'],J,'compact')

S('Output files and email notifications', '<div class="code-label">In analysis.sbatch, before executable commands</div><pre class=""><code>#SBATCH --output=analysis-%j.out\n#SBATCH --error=analysis-%j.err\n#SBATCH --mail-type=END,FAIL\n#SBATCH --mail-user=YOUR_NETID@illinois.edu</code></pre><table class=""><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td>--output / --error</td><td>Files for program output / error and diagnostic messages</td></tr><tr><td>%j</td><td>Slurm inserts the job ID: analysis-123457.out</td></tr><tr><td>--mail-type=END,FAIL</td><td>Ask for notification at job end or failure</td></tr><tr><td>--mail-user</td><td>The recipient; use your address or remove both mail lines</td></tr></tbody></table>', 'These lines let us choose where the job’s messages go. They’re already in the supplied analysis.sbatch template, before the commands that load software and run the analysis.\n\n--output names the file for ordinary program output. --error names the file for error and diagnostic messages. Some programs also put normal progress messages there, so we need to read what the .err file says before calling it a failure.\n\nThe useful part of these filenames is %j. Slurm fills that in with the job ID. For job 123457, analysis-%j.out becomes analysis-123457.out. We leave %j in the script; Slurm does the replacement. With these filenames, the logs go into the folder we submit from. If we add a subfolder to the path, that folder needs to exist before submission.\n\nFor email, --mail-type selects the events: END for the job ending and FAIL for failure. --mail-user is the recipient, so we put our own address there or remove both mail lines. Delivery depends on the cluster’s email setup. Even with a completion email, we still check the result.\n\nThe next two slides cover optional requests, starting with GPUs.', ['sbatch'], J, 'compact')

S('When the analysis needs a GPU',
  code('#SBATCH --partition=YOUR_GPU_PARTITION\n#SBATCH --gres=gpu:GPU_TYPE:1','Optional GPU job: use your group’s GPU partition and GPU type')+code('nvidia-smi','Inside an allocated NVIDIA GPU job')+rows([('--gres','Request GPUs with gpu:TYPE:COUNT; count is per node.'),('GPU_TYPE / final 1','The configured GPU type / one GPU per allocated node.')])+note('The tiny demo needs no GPU. Add this only for software that supports and uses one.'),
  'Some analysis tools can use a GPU, which is an additional processor for software that supports GPU computing. If a tool needs one, we first need an account and GPU partition that our group can use.\n\nIn --gres=gpu:GPU_TYPE:1, gpu names the resource, GPU_TYPE is the type name configured on the cluster, and the final 1 requests one GPU per allocated node. We get the valid names from the group’s documentation or support contact.\n\nReserving a GPU won’t make a CPU-only program use it. Inside an allocated NVIDIA GPU job, nvidia-smi shows the GPU visible to that job and some basic usage information. The GPU also has its own memory, separate from the CPU RAM we request with --mem.\n\nThe software needs a compatible environment too, so its installation instructions matter here. Our tiny demo stays on CPUs. Another optional setting is asking for a particular compute node; we’ll look at that next, because a node name and a GPU type refer to different things.',['jobs','sbatch'],J)

S('When a particular node is required',
  code('#SBATCH --nodes=1\n#SBATCH --nodelist=NODE_NAME','Optional: use a compute-node name your account can access')+code('sinfo -p YOUR_PARTITION -N','sinfo: inspect resources; -p selects the partition; -N lists nodes')+rows([('--nodes=1','How many nodes you request'),('--nodelist','Which named node you request')])+note('Normally let Slurm choose. Name a compute node only when your group requires that machine.'),
  "There are two similar-looking options here, but they mean different things. --nodes=1 says, “I need one computer.” --nodelist=NODE_NAME says, “I need this particular computer.” If we use it, NODE_NAME has to be a real compute node in a partition our account can access. We wouldn't put a login node here.\n\nTo look at the available resources, we can use sinfo. The -p option picks a partition, and -N lists the information by node. A node appearing in that list doesn't automatically mean our account has access to it.\n\nFor most jobs, I'd let Slurm choose a suitable node. Asking for one specific machine gives the scheduler fewer choices, so we may wait longer. It can make sense if the group needs that machine for a hardware test or comparison. But if we just need more memory or a certain GPU type, we can usually ask for that resource directly.\n\nThat's how we choose resources. Next, we'll use them to open a compute shell and prepare our software.",['sbatch','jobs'],J)

S('Open an interactive compute shell with srun',
  code('srun --account=YOUR_ACCOUNT --partition=YOUR_PARTITION \\\n  --nodes=1 --ntasks=1 --cpus-per-task=2 \\\n  --mem=4G --time=00:15:00 --pty bash','From the login shell in demo: paste this whole block as one command')+rows([('srun','Start a program on allocated compute resources.'),('--pty bash','Open an interactive terminal running the Bash shell.'),('After the prompt returns','hostname should show a compute node; pwd should show the project folder.')])+p('A trailing <code>\\</code> continues a command onto the next line; nothing follows it on that line.','small'),
  "We've been using the login node to organize files and submit jobs. For the software setup, we'll open a shell on a compute node so we can work there directly.\n\nWe start from the login shell, in demo. This srun command asks for one node, one task, two CPUs, four GiB of memory, and fifteen minutes. These are example settings for a small setup task. You'd replace YOUR_ACCOUNT and YOUR_PARTITION with the values approved for your group.\n\nAlthough the command takes up several lines on the slide, it's one command. Each backslash continues onto the next line, and nothing should come after it on that line. srun requests the resources and starts a program. Here, --pty bash gives us an interactive terminal running Bash on those resources.\n\nWe may have to wait in the queue. When the prompt appears, hostname should show a compute node, and pwd should still show our project folder. We'll prepare Python in this shell. VS Code's Run button and notebook cells don't automatically move to that compute node just because we've opened this shell.",['jobs','srun'],J,'compact')

S('Make Python available in the compute shell',
  code('module avail python\nmodule load python/3.11.11\nmodule list','Inside the allocation, in demo; use a version shown as available')+table(['Command','Meaning'],[['module avail python','List cluster modules matching Python'],['module load python/3.11.11','Select this installed Python version for this shell'],['module list','Confirm which cluster modules are loaded']])+note('analysis.py needs pandas. Next, create .venv in demo and install pandas there.'),
  "We're now in the compute shell, inside demo. Before we install any packages, we need to choose which Python we're using.\n\nThe cluster already has software installed. The module command lets our shell select from those installations. module avail python shows the Python choices. module load python/3.11.11 selects this example version, and module list lets us check what's loaded. The number after the slash is the version. Use one that's actually available, and keep the same version when we write the batch job later.\n\nHaving Python available is only part of the setup. Our script, analysis.py, uses pandas to read a table. pandas is a package: reusable code that the script can import. We still need to install it for the Python we're using.\n\nWe'll do that inside a project environment. One naming detail before we move on: the cluster's module command and Python's -m option are different things. We'll use -m in the next step.",['software'],P)

S('Create a Python environment and install pandas',
  code('python -m venv .venv\nsource .venv/bin/activate\npython -m pip install pandas\nls -a','Continue in the same compute shell and remote demo folder')+rows([('Create .venv','-m runs Python’s venv utility; .venv is the new folder.'),('Activate','source makes this shell use .venv/bin/python.'),('Install pandas','-m pip runs the package installer for the selected Python.')])+p('Wait for pip to finish and the prompt to return. Then check the import on the next slide.','small'),
  "We'll keep working in the same compute shell and demo folder. The first line creates an environment called .venv. That gives this project its own place to install Python packages. In python -m venv, -m tells Python to run its venv tool, and .venv is the folder we want it to create.\n\nThe next line activates that environment. source .venv/bin/activate tells this shell to use .venv/bin/python when we type python. No packages are downloaded by activation itself.\n\nThen python -m pip install pandas runs the package installer through that Python and asks it to install pandas. We wait for it to finish and for the prompt to come back. Afterward, ls -a shows the hidden .venv folder too.\n\nThese files belong here on the cluster. We create this environment here instead of copying one from a laptop. And activation only applies to this shell; a new shell or batch job will need to select the environment again.\n\nBefore we leave this shell, let's check that Python can actually load pandas.",['python','python_cli','software'],P,'compact')

S('Check that pandas imports and save package versions',
  code('python -c "import pandas; print(pandas.__version__)"','-c executes the quoted Python code immediately')+rows([('import pandas','Check that this Python can load the package.'),('Print version','print(pandas.__version__) displays the installed version; expect a version number.')])+code('python -m pip freeze > requirements.txt','freeze lists installed package versions; > writes them into this file')+note('Continue when a version prints without an error. Keep this compute shell open.'),
  "I'd check the package before trying the whole analysis. That way, if something's missing, we find out at this step.\n\nThe environment is still active. Python's -c option runs the code inside the quotation marks. import pandas loads the package, and print(pandas.__version__) prints its version number. The semicolon separates those two instructions, and __version__ holds the package's version information.\n\nWe're looking for a version number with no import error. Your number may be different from someone else's. If it fails, check that the chosen Python module is loaded, activate .venv again, and check whether installation finished without errors. A download finishing doesn't by itself show that Python can use the package.\n\nThe second command saves a record of the installed versions. pip freeze lists them, and the greater-than sign writes the list into requirements.txt. It replaces that file if it already exists. This records what we've installed; it doesn't install the packages again.\n\nKeep this compute shell open for a moment. The next diagram shows what will stay after we close it.",['python','python_cli','software'],P,'compact')

S('The environment stays; activation is per shell',
  concept_diagram('install-activate')+note('After setup, <code>exit</code> returns to the login shell; .venv stays in project storage.'),
  "This is a distinction that's easy to mix up: installing a package and activating an environment are two separate steps.\n\nIn the top row, pip puts pandas and the packages it depends on into .venv. Those are files in our project storage. They're still there after the compute shell closes.\n\nIn the bottom row, activation tells the current shell to use .venv/bin/python. We're selecting files that already exist. We're not reinstalling them, and we're not requesting a compute node. When a batch job starts later, it'll load the same compatible Python module and activate this same environment. Activating it here doesn't activate it in every other terminal or job.\n\nThen, inside a Python program, import pandas loads the installed package so the program can use it.\n\nOur setup is finished, so exit takes us out of the compute shell and releases this interactive allocation. We can check hostname and pwd to confirm we're back on the login node in the project folder. If the allocation has already ended, check the host before typing exit again.\n\nOur .venv is ready for its batch job. Before that, I'll show the alternative you may see in other projects: Conda.",['python','radmin'],P,'concept-slide'),

S('Create a Conda environment from a supplied file',
  code('module avail miniconda3\nmodule load YOUR_CONDA_MODULE\nconda env create -f environment.yml\nconda run -n analysis python -c "import pandas; print(pandas.__version__)"','Alternative route when the project supplies environment.yml')+rows([('environment.yml','Records the environment name and requested packages'),('-f environment.yml','Read the environment specification from this file.'),('-n analysis','Use the environment named analysis (from name: analysis in the file).')])+p('Choose this instead of .venv. In a new compute shell, expect a pandas version with no error.','small'),
  "You may download a project and find an environment.yml file with it. That file gives Conda the environment name and the packages to install. You'd use this route instead of creating .venv. We don't need to do both for our example.\n\nOur supplied file is in examples, so it needs to be copied into the remote project first. We'd open a new compute shell for this setup. Conda may use space in home, so run quota to check your usage before starting. If home is nearly full, ask your group's technical contact where the environment should go.\n\nmodule avail miniconda3 shows the available Conda modules. Replace YOUR_CONDA_MODULE with the one you're going to load. Then conda env create builds the environment, and -f tells it which file to read. Our file names the environment analysis.\n\nIn the last command, conda run -n analysis means “run this command in the environment named analysis.” The Python part checks that pandas imports and prints its version. We want that to finish without an error before moving on.\n\nAfter the check, exit leaves the setup shell. For the next slide, we're returning to the .venv we already prepared and putting its setup into a batch job.",['conda','software'],P)

S('Prepare a Python batch job with its environment',
  cols(code('#!/bin/bash\n#SBATCH --job-name=analysis\n#SBATCH --account=YOUR_ACCOUNT\n#SBATCH --partition=YOUR_PARTITION\n#SBATCH --nodes=1\n#SBATCH --ntasks=1\n#SBATCH --cpus-per-task=1\n#SBATCH --mem=1G\n#SBATCH --time=00:05:00','1 · Beginning of analysis.sbatch'),code('#SBATCH --output=analysis-%j.out\n#SBATCH --error=analysis-%j.err\n\nset -e\nmodule load python/3.11.11\nsource .venv/bin/activate\npython analysis.py','2 · Continue in the same file, after the left column'))+note('set -e stops on setup failure. Set your account and partition, then save analysis.sbatch.'),
  "We have the software ready, so we can tell the batch job how to use it. Both columns here belong to one file, analysis.sbatch. Read down the left column, then continue down the right. All the #SBATCH settings go before the commands that actually run.\n\nWe're requesting one node, one task, one CPU, one GiB of memory, and five minutes. That's for this small example; a real analysis needs settings that fit its software and data.\n\nThe output and error lines name our two log files. Slurm fills in %j with the job ID and writes the logs in the folder where we submitted the job. The downloadable template also has email settings. Put in your own address, or remove both email lines.\n\nBelow those settings, set -e stops this script if a setup command fails. Then we load the same Python module we used earlier, activate the existing .venv, and run analysis.py. It reuses the packages we installed earlier.\n\nOnce the account, partition, and Python module are correct, save analysis.sbatch in VS Code. Then we're ready to submit it.",['software','sbatch','python'],R,'compact')

S('Submit the analysis job',
  code('pwd\nls data/samples.csv analysis.py analysis.sbatch\nsbatch analysis.sbatch','In the login shell, from the demo folder')+code('Submitted batch job 123457','Illustrative analysis job ID; hello used 123456')+code('squeue -u YOUR_NETID','Check whether this new job is pending or running')+note('Use the returned ID in analysis-JOBID.out and analysis-JOBID.err.'),
  "At this point, we have the input, the Python script, the batch file, and the environment. We're back in the login shell, and our terminal should be in the remote demo folder.\n\nI like to check the location and files before submitting. pwd tells us where we are. The ls command checks for data/samples.csv, analysis.py, and analysis.sbatch. Then sbatch analysis.sbatch submits the saved job file.\n\nThe job ID 123457 on the slide is an example. In your own session, keep the job ID Slurm actually returns. This analysis job has a different ID from our earlier hello job, so we'll use the new number when we open its logs.\n\nsqueue -u YOUR_NETID shows your jobs. PD means this one is waiting; R means it's running. Our log names will be analysis-JOBID.out and analysis-JOBID.err, with the returned number in place of JOBID. They may not show up until the job starts running.\n\nOnce a log appears, we can watch it to see what the program is doing.",['sbatch','jobs'],R)

S('Watch job output and search the error log',
  code('tail -n 20 analysis-123457.out\ntail -f analysis-123457.out','After the analysis job starts and the log exists')+code('grep -in "error" analysis-123457.err','First press Ctrl+C to stop tail; then search the error log')+rows([('Ctrl+C','Stop tail; the submitted job keeps running.'),('Need to cancel?','scancel 123457 cancels this analysis job.')])+note('tail: -n 20 = last 20 lines, -f = follow new output · grep: -i = ignore case, -n = line numbers'),
  "Once the log exists, tail lets us check its latest output while the analysis runs. Use the current job's ID in the filename.\n\ntail -n 20 shows the last twenty lines and gives us the prompt back. tail -f stays open and shows new lines as the program writes them. That's useful when we want to follow its progress.\n\nWhile tail -f is running, that terminal is busy watching the file. Ctrl+C stops the viewer, so we can type another command. The submitted job keeps running. If we actually want to cancel the job, we'd use scancel with its job ID.\n\nAfter leaving tail, we can search the error log with grep. Here, -in combines two options: -i ignores letter case and -n adds line numbers. So this finds lines containing “error” and tells us where they are. We still need to read what the message says. No match doesn't prove success, and a nonempty .err file doesn't always mean failure; some programs put ordinary status messages there.\n\nLet's also open the result and check what the analysis produced.",['shell','cli','jobs'],R,'compact')

S('Open the result in VS Code',
  rows([('Explorer → results','Open an output table; check its column names and sample count.'),('Keep it remote','Read or edit the file without downloading it first.'),('Need a local copy?','Right-click summary.csv and choose Download…')])+table(['Other output types','Viewer'],[['Logs / PNG / JPEG','Built-in text or image viewer'],['CSV / TSV','Text editor; Rainbow CSV adds column colors'],['PDF / notebooks','A PDF viewer extension / Microsoft Jupyter viewer']]),
  "We can go straight back to Explorer to look at the result. It's the same VS Code window we've been using. Refresh the folder if needed, expand results, and open the output table.\n\nI'd start with two simple checks: are the columns we expected there, and does the sample count match the input? If the file is empty or looks incomplete, we'd go back to the logs to find out why.\n\nWe can read the file right here on the cluster. If we want a copy on the laptop, we can right-click summary.csv and choose Download.\n\nThe viewer depends on the file type. Text and images open directly. Rainbow CSV adds colors that help separate table columns. PDFs and notebooks use suitable extensions. When installing one, follow the prompt for the local or SSH environment.\n\nOpening a notebook is just opening the file. It doesn't reserve compute resources. Check where its cells will run, and keep substantial analysis off the login node.\n\nWe've followed a Python job through to its result. The same basic process works for R too.",['vscode','csv','pdf','jupyter','transfer'],R,'compact')

S('Run an R script as a Slurm batch job',
  code('module load R\nRscript analysis.R','R commands below the #SBATCH resource settings')+code('sbatch analysis_R.sbatch','Copy analysis.R and analysis_R.sbatch into the project; set the account and partition')+rows([('Same input','data/samples.csv'),('R output','results/summary_R.csv')])+note('This example uses base R; no additional package installation is needed.'),
  "If you mainly work in R, the Slurm part will look very familiar. We still submit a batch file, check the queue, and read the logs. We change the software we load and the command that runs our script.\n\nThe examples folder includes analysis.R and analysis_R.sbatch. Copy them into the remote project that contains data/samples.csv, and put your approved account and partition into the batch file.\n\nInside that file, module load R selects the cluster's R installation. Use an R module name that's available on the system. Rscript analysis.R runs the saved script, so we don't need to open an interactive R console.\n\nThis particular example uses only base R, which means it doesn't need extra packages or a custom package library. If your own script uses additional packages, those need to be prepared before the job runs. Our example writes its result to results/summary_R.csv.\n\nAfter sbatch returns a job ID, the routine is the same: check the queue and logs, then open the result. If something goes wrong along the way, the error message usually tells us where to start looking.",['software','sbatch'],R,'compact')

S('Common errors and the first useful check',
  table(['What you see','Check first'],[['No such file or directory','Run pwd; check the path and filename capitalization.'],['Command not found','Check spelling; load the module or activate the environment.'],['No module named… / no package called…','Select the intended Python/R environment; install the missing package there.'],['OUT_OF_MEMORY / TIMEOUT','Compare --mem / --time with the tool’s documented requirements.'],['Invalid account / partition','Use your approved --account and matching --partition.'],['Permission denied / quota exceeded','Run quota; confirm the group gave you write access to that folder.']]),
  "Errors are part of getting a job set up. The useful thing is to look at the message before submitting the same file again, because an unchanged submission will usually hit the same problem.\n\nIf a file can't be found, I'd check pwd, then the path and the spelling, including capital letters. If a command can't be found, check its spelling and whether the right module or environment is selected. For a missing Python or R package, check the environment the job actually uses, and install the package there.\n\nOUT_OF_MEMORY means the job exceeded its memory allowance. TIMEOUT means it reached its time limit. Look at --mem or --time alongside the error log and the software's documented requirements before changing the request.\n\nFor an invalid account or partition, check that they're an approved pair. For a quota error, quota shows usage and limits. For Permission denied, ask your group to confirm that you can write to that folder.\n\nAnd when you ask for help, include the job ID, the batch script, the exact error, and the software version. Those details give your lab contact or ICC support something useful to work with. They don't need your password or a copy of the whole dataset.",['jobs','software','storage'],R,'compact')

S('Documentation and help',
  '<div class="source-columns">'+''.join(f'<div><a href="{SOURCES[k][1]}" target="_blank">{E(SOURCES[k][0])}</a></div>' for k in ['access','jobs','storage','software','shell','cli','vscode','sbatch','python','bioc','conda','reveal'])+'</div>'+p('ICC support: <strong>help@campuscluster.illinois.edu</strong><br>Full references and image credits are in SOURCES.md.','small'),
  "You don't need to memorize all of these commands today. These links are here when you need the details for your own project.\n\nI'd start with the ICC guide for this cluster's accounts, storage, software, and job submission. Missing Semester explains the shell concepts we've been using. The Microsoft and software documentation covers the editor, environments, and individual options.\n\nFor account-specific problems, ICC support can check things a general tutorial can't. Send the job ID and exact error, along with the relevant job file and software version.\n\nWe've gone from connecting to the cluster all the way to opening a result: choose a project folder, prepare the software, request resources, submit the script, then check the logs and output. Our examples are deliberately small. For your own analysis, replace the placeholders and choose software versions and resources that fit the project.\n\nThat gives you a starting point for running your own work on the Campus Cluster. Thanks, everyone.",[],R)
